// Hyperspectral cubes. A band listed as bad in the header's bbl reads as NaN.
export function readBand(cube, index) {
  if (cube.badBands.includes(index)) return new Float32Array(cube.width * cube.height).fill(NaN);
  return cube.bands[index];
}

