import { readBand } from './cube.js';

export function covariance(cube) {
  const bands = [];
  for (let b = 0; b < cube.bandCount; b += 1) bands.push(readBand(cube, b));
  const pixels = cube.width * cube.height;
  const mean = bands.map((band) => band.reduce((sum, v) => sum + v, 0) / pixels);
  const n = bands.length;
  const cov = Array.from({ length: n }, () => new Float64Array(n));
  for (let i = 0; i < n; i += 1) {
    for (let j = i; j < n; j += 1) {
      let sum = 0;
      for (let p = 0; p < pixels; p += 1) sum += (bands[i][p] - mean[i]) * (bands[j][p] - mean[j]);
      cov[i][j] = cov[j][i] = sum / (pixels - 1);
    }
  }
  return { mean, cov };
}
